//! Gold: `table_extractors` is 1:1 with the live
//! `harness/electronics/table_extractors.py`.
//!
//! `tests/fixtures/gold/table_extractors_v1.json` was generated by
//! `scripts/gold_table_extractors.py` — kernel cases call the pure parsers
//! over the table shapes the pytest pins (`None`/`0`/numeric cells exactly
//! as `extract()` returns them).
//!
//! The cases pin the traps the parsers exist for: printed physical ids stay
//! verbatim (`1`, `A1`, `12(1)`, numeric `0` is a real identifier and
//! serializes to `"0"`), a `Pin name` column is never a pin number,
//! semantic fields are field-aligned and value-filtered (`-`/`—`/`N/A`
//! print no value), parametric rows keep every printed column verbatim and
//! expand to conversion-free facts with `description` preferred over
//! `symbol` and `typ.` folding to the `typ` role, unselected package
//! columns drop while shared semantics stay, and parametric headers need a
//! parameter field plus 2+ value-role headers.

#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::indexing_slicing,
    clippy::too_many_lines,
    clippy::cast_possible_truncation,
    clippy::doc_markdown,
    clippy::panic,
    reason = "gold tests assert on their own fixtures"
)]

use std::path::PathBuf;

use serde_json::Value;

use dw_recon::table_extractors::{
    normalize_parametric_facts, parse_parametric_table, parse_pin_table, physical_pin_identifiers,
    pin_identity_rows, pin_semantic_roles, pin_semantic_values, project_pin_table,
};

fn gold_path() -> PathBuf {
    let mut dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    while !dir.join("tests/fixtures/gold").is_dir() {
        assert!(dir.pop(), "could not locate tests/fixtures/gold");
    }
    dir.join("tests/fixtures/gold/table_extractors_v1.json")
}

fn gold() -> Value {
    serde_json::from_str(&std::fs::read_to_string(gold_path()).unwrap()).unwrap()
}

#[test]
fn every_case_matches_the_live_reference() {
    let g = gold();
    let mut checked = 0;
    for case in g["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        let got: Value = match case["kind"].as_str().unwrap() {
            "parse_pin_table" => serde_json::to_value(parse_pin_table(
                &input["table"],
                input["document_sha256"].as_str().unwrap(),
                input["page_1based"].as_i64().unwrap(),
            ))
            .unwrap(),
            "parse_parametric_table" => serde_json::to_value(parse_parametric_table(
                &input["table"],
                input["document_sha256"].as_str().unwrap(),
                input["page_1based"].as_i64().unwrap(),
            ))
            .unwrap(),
            "normalize_parametric_facts" => {
                let order: Vec<String> = input["key_order"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|k| k.as_str().unwrap().to_string())
                    .collect();
                serde_json::to_value(normalize_parametric_facts(&input["row"], &order)).unwrap()
            }
            "physical_pin_identifiers" => {
                serde_json::to_value(physical_pin_identifiers(Some(&input["value"]))).unwrap()
            }
            "pin_identity_rows" => {
                serde_json::to_value(pin_identity_rows(&input["table"])).unwrap()
            }
            "pin_semantic_roles" => {
                serde_json::to_value(pin_semantic_roles(&input["table"])).unwrap()
            }
            "pin_semantic_values" => {
                let values = pin_semantic_values(
                    &input["table"],
                    input["row_index"].as_u64().unwrap() as usize,
                    Some(&input["pin_no"]),
                    Some(&input["name"]),
                );
                let mut map = serde_json::Map::new();
                for (key, list) in values {
                    map.insert(key, serde_json::to_value(list).unwrap());
                }
                Value::Object(map)
            }
            "project_pin_table" => {
                project_pin_table(&input["table"], input["selected_header"].as_str().unwrap())
            }
            other => panic!("unknown gold case kind {other}"),
        };
        assert_eq!(got, case["expected"], "case {name}");
        checked += 1;
    }
    assert_eq!(checked, g["cases"].as_array().unwrap().len());
}
